def validate_raw(topics, name):
    assert len(topics) == 100, f"Expected 100 {name} topics, got {len(topics)}"
    seen_titles = set()
    for item in topics:
        assert len(item) == 6, f"Malformed topic tuple in {name}: {item}"
        title, subj, sys_name, action, cit_title, cit_url = item
        assert title not in seen_titles, f"Duplicate title in {name}: {title}"
        seen_titles.add(title)
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {name}: {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {name}: {title}"
        assert len(action) >= 20, f"Action too short in {name}: {action}"
        assert cit_url.startswith("https://"), f"Invalid citation URL in {name}: {cit_url}"
    print(f"Validated 100 {name} topics successfully.")

if __name__ == "__main__":
    validate_raw(AMC_RAW, "AMC")
    validate_raw(MCCQE_RAW, "MCCQE")
    validate_raw(NEET_RAW, "NEET PG")

    out_file = os.path.join(os.path.dirname(__file__), "mega46_topics_b.py")
    with open(out_file, "w", encoding="utf-8") as f:
        f.write('"""Generated topics for Mega-Batch 46 Part B (AMC, MCCQE, NEET)"""\n\n')
        f.write(f"AMC_TOPICS = {repr(AMC_RAW)}\n\n")
        f.write(f"MCCQE_TOPICS = {repr(MCCQE_RAW)}\n\n")
        f.write(f"NEET_TOPICS = {repr(NEET_RAW)}\n")

    print(f"Wrote {out_file} successfully.")
